function updateFleet(count) {
  const fleet = document.getElementById("truckFleet");
  fleet.innerHTML = "";

  for (let i = 0; i < count; i++) {
    const truck = document.createElement("div");
    truck.className = "fleet-truck";
    truck.textContent = "🚛";
    truck.title = "Жүк көлігі №" + (i + 1);
    truck.style.top = (39 + (i % 5) * 9) + "%";
    truck.style.animationDelay = (-i * 1.7) + "s";
    truck.style.animationDuration = (7 + (i % 4)) + "s";
    fleet.appendChild(truck);
  }
}

function updateMine() {
  const e = Number(excavators.value);
  const t = Number(trucks.value);

  const excavatorCapacity = e * 400;
  const truckCapacity = t * 90 * 3;
  const production = Math.min(excavatorCapacity, truckCapacity);

  document.getElementById("excavatorCount").textContent = e;
  document.getElementById("truckCount").textContent = t;
  updateFleet(t);

  document.querySelectorAll(".card strong")[0].textContent = e;
